/\n/// Existe porque la misma foto se usa en más de un lado —el abono en su ficha y\n/// en la del combo que lo incluye— y sin una biblioteca había que subirla dos\n/// veces: dos objetos en R2, y renombrar uno dejaba al otro viejo.\nmodel Media {\n  id          String  @id @default(cuid())\n  /// Dónde vive en R2. Único: es el archivo, y dos filas apuntando al mismo\n  /// harían que borrar una dejara a la otra colgada de un objeto que ya no está.\n  key         String  @unique\n  /// Cómo se llamaba el archivo al subirlo. Es con lo que se lo busca en la\n  /// biblioteca: el `key` es un uuid y no le dice nada a nadie.\n  nombre      String\n  /// Para lectores de pantalla y para cuando la imagen no carga.\n  alt         String?\n  contentType String\n\n  createdAt   DateTime @default(now())\n  createdById String?\n  createdBy   User?    @relation(\"MediaCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n\n  productos     ProductoImagen[]\n  categorias    Categoria[]\n  informesFotos InformeSeccionFoto[]\n\n  @@index([createdAt])\n}\n\n/// Qué imágenes de la biblioteca usa un producto, y en qué orden.\n///\n/// Sacar una de acá la saca **del producto**, no de la biblioteca: la foto\n/// sigue disponible para otro. Borrarla de verdad es otra acción, y la FK a\n/// `Media` es `Restrict` para que no se pueda mientras algún producto la use.\nmodel ProductoImagen {\n  id         String @id @default(cuid())\n  productoId String\n  mediaId    String\n  posicion   Int    @default(0)\n\n  createdAt DateTime @default(now())\n\n  producto  Producto   @relation(fields: [productoId], references: [id], onDelete: Cascade)\n  media     Media      @relation(fields: [mediaId], references: [id], onDelete: Restrict)\n  variantes Variante[]\n\n  /// La misma foto no entra dos veces en el mismo producto.\n  @@unique([productoId, mediaId])\n  @@index([productoId, posicion])\n  @@index([mediaId])\n}\n\n/// Por qué se movió el stock.\nenum MotivoMovimiento {\n  /// Entró mercadería.\n  INGRESO\n  /// Corrección a mano, con su nota.\n  AJUSTE\n  /// Una toma de inventario: la cantidad pasa a ser la contada.\n  CONTEO\n  /// Salió por una venta.\n  VENTA\n  /// Volvió por una devolución.\n  DEVOLUCION\n}\n\n/// Cada vez que el stock de una variante cambió, y por qué.\n///\n/// **El stock se lleva en un libro**, igual que las ventas. Un número suelto\n/// contesta \"cuánto hay\" y ninguna otra pregunta: quién lo cambió, cuándo, y\n/// contra qué. Cuando alguien discute un conteo, lo que se mira es esto.\nmodel MovimientoInventario {\n  id         String @id @default(cuid())\n  varianteId String\n\n  /// Positivo entra, negativo sale.\n  cantidad Int\n  /// Cuánto quedó después de este movimiento, congelado. Sin esto, saber cómo\n  /// estaba el stock en una fecha obliga a sumar el libro entero desde cero.\n  saldo    Int\n  motivo   MotivoMovimiento\n  nota     String?\n\n  /// Qué factura lo movió, en un `VENTA` o una `DEVOLUCION`. Es lo que hace\n  /// que \"¿por qué bajó?\" se pueda contestar sin adivinar. `SetNull` y no\n  /// `Restrict`: el movimiento pasó y sigue siendo cierto aunque la factura se\n  /// vaya de la base.\n  facturaId String?\n\n  createdAt       DateTime @default(now())\n  createdById     String?\n  /// El nombre al momento de moverlo: el id se vacía si borran la cuenta, y un\n  /// movimiento sin autor no se puede explicar. El mismo par que usan\n  /// `Factura` y `OrdenLinea`.\n  createdByNombre String?\n\n  variante  Variante @relation(fields: [varianteId], references: [id], onDelete: Cascade)\n  factura   Factura? @relation(fields: [facturaId], references: [id], onDelete: SetNull)\n  createdBy User?    @relation(\"MovimientoCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n\n  @@index([varianteId, createdAt])\n  @@index([facturaId])\n}\n\n/// Un contrato recurrente. Agrupa uno o más productos que se cobran juntos en\n/// el mismo ciclo: cada renovación genera una orden con una línea por ítem.\nmodel Suscripcion {\n  id           String         @id @default(cuid())\n  /// Número corto para nombrarla: \"Suscripción #12\".\n  ///\n  /// Secuencia **propia**, independiente de la de órdenes. Que exista una orden\n  /// #12 y una suscripción #12 a la vez está bien: son cosas distintas y en\n  /// pantalla siempre van con su prefijo. Compartir una sola secuencia las\n  /// dejaría salteadas —#3, #17, #40— sin ganar nada a cambio.\n  numero       Int            @unique @default(autoincrement())\n  clienteId    String\n  estado       EstadoServicio @default(ACTIVO)\n  /// El ciclo lo define la suscripción, no el producto: el mismo producto puede\n  /// ser mensual para un cliente y trimestral para otro.\n  periodicidad Periodicidad   @default(MENSUAL)\n  fechaInicio  DateTime       @db.Date\n  fechaFin     DateTime?      @db.Date\n  notas        String?        @db.Text\n\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n  createdById String?\n  updatedById String?\n\n  cliente   Cliente           @relation(fields: [clienteId], references: [id], onDelete: Cascade)\n  createdBy User?             @relation(\"SuscripcionCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  updatedBy User?             @relation(\"SuscripcionUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull)\n  items     SuscripcionItem[]\n  ordenes   Orden[]\n  visitas   Visita[]\n\n  @@index([clienteId, estado])\n}\n\n/// Un producto dentro de una suscripción, con su propio precio e IVA. La tasa\n/// va acá y no en la cabecera porque una misma factura puede mezclar líneas al\n/// 0% y al 15%.\nmodel SuscripcionItem {\n  id                String  @id @default(cuid())\n  suscripcionId     String\n  productoId        String\n  precio            Decimal @db.Decimal(10, 2)\n  ivaTasa           Decimal @default(0) @db.Decimal(5, 2)\n  /// Visitas que incluye **por período de cobro**: en una trimestral son las\n  /// del trimestre. Es informativo — no es un tope, se puede agendar de más.\n  visitasPorPeriodo Int?\n\n  suscripcion     Suscripcion      @relation(fields: [suscripcionId], references: [id], onDelete: Cascade)\n  producto        Producto         @relation(fields: [productoId], references: [id], onDelete: Restrict)\n  visitaProductos VisitaProducto[]\n  ordenLineas     OrdenLinea[]\n\n  @@unique([suscripcionId, productoId])\n  @@index([productoId])\n}\n\nmodel Personal {\n  id           String    @id @default(cuid())\n  nombre       String\n  apellido     String?\n  telefono     String?\n  especialidad String?\n  sueldo       Float?\n  tipo         String?\n  estado       String    @default(\"ACTIVO\")\n  userId       String?   @unique\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n  deletedAt    DateTime?\n\n  createdById String?\n  updatedById String?\n  createdBy   User?   @relation(\"JardineroCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  updatedBy   User?   @relation(\"JardineroUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull)\n\n  user    User?            @relation(fields: [userId], references: [id], onDelete: SetNull)\n  grupos  GrupoMiembro[]\n  visitas VisitaPersonal[]\n}\n\nmodel Grupo {\n  id          String    @id @default(cuid())\n  nombre      String\n  descripcion String?   @db.Text\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n  deletedAt   DateTime?\n\n  createdById String?\n  updatedById String?\n  createdBy   User?   @relation(\"GrupoCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  updatedBy   User?   @relation(\"GrupoUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull)\n\n  miembros GrupoMiembro[]\n  visitas  Visita[]\n}\n\nmodel Visita {\n  id                  String       @id @default(cuid())\n  /// Número corto para nombrarla: \"Visita #34\".\n  ///\n  /// Secuencia propia, como la de órdenes y suscripciones. En pantalla siempre\n  /// va con su prefijo, así que que coexistan la orden #34 y la visita #34 no\n  /// confunde a nadie.\n  numero              Int          @unique @default(autoincrement())\n  clienteId           String\n  /// De qué plan es esta visita, si es de alguno.\n  ///\n  /// La decisión es **de la visita**, no de cada producto: \"esta visita es del\n  /// plan mensual\" o \"esta visita es un trabajo aparte\". Con el plan puesto,\n  /// cada producto que **esté en ese plan** queda cubierto —eso ya no se\n  /// decide, se deduce del plan— y lo que no esté se cobra como trabajo suelto.\n  ///\n  /// En null, todo lo que se haga se cobra aparte. Es lo que permite hacerle a\n  /// alguien una visita extra de algo que igual tiene contratado.\n  suscripcionId       String?\n  fechaProgramada     DateTime     @db.Date\n  fechaRealizada      DateTime?    @db.Date\n  horaEntrada         String?\n  horaSalida          String?\n  estado              EstadoVisita @default(PROGRAMADA)\n  grupoId             String?\n  notas               String?      @db.Text\n  notasIncompleto     String?      @db.Text\n  createdAt           DateTime     @default(now())\n  updatedAt           DateTime     @updatedAt\n  deletedAt           DateTime?\n  createdById         String?\n  updatedById         String?\n  /// El nombre de quien la tocó al final, tal como se llamaba entonces.\n  ///\n  /// Junto al id y no en su lugar: el id sirve para filtrar por persona, pero\n  /// se queda sin dueño si la cuenta se elimina, y si alguien se cambia el\n  /// apellido no corresponde reescribir lo que ya pasó. El texto es lo que se\n  /// muestra; el id, lo que se consulta.\n  updatedByNombre     String?\n  /// Cuándo se cerró como completada, y quién apretó el botón.\n  ///\n  /// No es `fechaRealizada`: esa es el **día en que se hizo el trabajo**, la\n  /// elige quien la cierra y puede ser anterior —el lunes se cierra una visita\n  /// hecha el viernes—. Esto es el instante en que quedó registrada.\n  ///\n  /// Y no es `updatedById`: ese es el último que la tocó por cualquier motivo,\n  /// así que una corrección de fecha tres semanas después borra el rastro de\n  /// quién la completó. Por eso son campos aparte.\n  ///\n  /// Se ponen al pasar a COMPLETADA y se limpian si sale de ese estado: si la\n  /// visita ya no está completada, no hay nadie que la haya completado.\n  completadaEl        DateTime?\n  completadaPorId     String?\n  /// El nombre de quien la completó, congelado en ese momento. Ver\n  /// `updatedByNombre`: mismo motivo.\n  completadaPorNombre String?\n\n  cliente        Cliente           @relation(fields: [clienteId], references: [id], onDelete: Cascade)\n  productos      VisitaProducto[]\n  grupo          Grupo?            @relation(fields: [grupoId], references: [id], onDelete: SetNull)\n  createdBy      User?             @relation(\"VisitaCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  updatedBy      User?             @relation(\"VisitaUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull)\n  completadaPor  User?             @relation(\"VisitaCompletadaPor\", fields: [completadaPorId], references: [id], onDelete: SetNull)\n  media          VisitaMedia[]\n  personal       VisitaPersonal[]\n  notificaciones NotificacionLog[]\n  messages       VisitaMessage[]\n  chatReads      VisitaChatRead[]\n  informes       InformeVisita[]\n  ordenes        OrdenVisita[]\n  suscripcion    Suscripcion?      @relation(fields: [suscripcionId], references: [id], onDelete: SetNull)\n\n  @@index([clienteId])\n  @@index([suscripcionId])\n  @@index([fechaProgramada])\n  /// Para filtrar \"completadas entre estas fechas\" sin recorrer la tabla.\n  @@index([completadaEl])\n}\n\n/// Una visita puede cubrir varios servicios contratados del mismo cliente.\n/// Un producto cubierto por una visita. Una visita puede cubrir varios.\n///\n/// **No lleva plata.** El precio de un trabajo se decide al facturarlo, en la\n/// orden, igual que todo el resto del dinero del sistema. Acá solo vive el\n/// hecho: qué se hizo y si estaba cubierto por un plan.\nmodel VisitaProducto {\n  id                String    @id @default(cuid())\n  visitaId          String\n  /// Qué se hizo. Siempre presente, venga de una suscripción o sea trabajo suelto.\n  productoId        String\n  /// Puesto = el plan lo cubre y no se cobra aparte. Null = trabajo suelto, se\n  /// factura creando una orden. No es plata: es cobertura.\n  suscripcionItemId String?\n  /// En qué lugar de la lista va, nada más. Se llamaba `orden` y se leía como\n  /// \"a qué orden pertenece\", que es justo lo que **no** es: eso vive en\n  /// `OrdenLinea.visitaProductoId`. `OrdenLinea` ya usaba `posicion` para lo\n  /// mismo.\n  posicion          Int       @default(0)\n  /// Cuándo se soltó de una orden anulada.\n  ///\n  /// Anular libera la procedencia, así que el trabajo vuelve a \"pendiente\" y no\n  /// queda ni rastro de que alguna vez estuvo facturado. Sin esta marca, el\n  /// proceso que arma borradores lo volvería a agarrar y pisaría la decisión de\n  /// no cobrarlo. Facturarlo a mano sigue siendo posible: esto solo frena a los\n  /// automatismos.\n  liberadoAt        DateTime?\n\n  visita           Visita            @relation(fields: [visitaId], references: [id], onDelete: Cascade)\n  producto         Producto          @relation(fields: [productoId], references: [id], onDelete: Restrict)\n  suscripcionItem  SuscripcionItem?  @relation(fields: [suscripcionItemId], references: [id], onDelete: SetNull)\n  /// Dónde se cobró, si ya se cobró. El id es único en `OrdenLineaOrigen`, así\n  /// que esto es a lo sumo uno: un trabajo se factura una sola vez.\n  ordenLineaOrigen OrdenLineaOrigen?\n\n  @@unique([visitaId, productoId])\n  @@index([productoId])\n  @@index([suscripcionItemId])\n}\n\nmodel VisitaPersonal {\n  id          String    @id @default(cuid())\n  visitaId    String\n  personalId  String\n  addedAt     DateTime  @default(now())\n  addedById   String?\n  removedAt   DateTime?\n  removedById String?\n\n  visita    Visita   @relation(fields: [visitaId], references: [id], onDelete: Cascade)\n  personal  Personal @relation(fields: [personalId], references: [id], onDelete: Cascade)\n  addedBy   User?    @relation(\"VisitaPersonalAddedBy\", fields: [addedById], references: [id], onDelete: SetNull)\n  removedBy User?    @relation(\"VisitaPersonalRemovedBy\", fields: [removedById], references: [id], onDelete: SetNull)\n\n  @@unique([visitaId, personalId])\n}\n\nmodel VisitaMedia {\n  id        String   @id @default(cuid())\n  visitaId  String\n  key       String\n  url       String\n  tipo      String\n  createdAt DateTime @default(now())\n\n  /// Etiqueta opcional: a cuál de los productos de la visita corresponde la foto.\n  productoId String?\n\n  visita       Visita               @relation(fields: [visitaId], references: [id], onDelete: Cascade)\n  producto     Producto?            @relation(fields: [productoId], references: [id], onDelete: SetNull)\n  informeFotos InformeSeccionFoto[]\n\n  @@index([visitaId])\n  @@index([productoId])\n}\n\nmodel VisitaMessage {\n  id           String   @id @default(cuid())\n  visitaId     String\n  authorUserId String\n  body         String?  @db.Text\n  createdAt    DateTime @default(now())\n\n  visita Visita               @relation(fields: [visitaId], references: [id], onDelete: Cascade)\n  author User                 @relation(fields: [authorUserId], references: [id], onDelete: Cascade)\n  media  VisitaMessageMedia[]\n\n  @@index([visitaId, createdAt])\n  @@index([authorUserId])\n}\n\nmodel VisitaMessageMedia {\n  id        String   @id @default(cuid())\n  messageId String\n  key       String\n  url       String\n  tipo      String\n  createdAt DateTime @default(now())\n\n  message VisitaMessage @relation(fields: [messageId], references: [id], onDelete: Cascade)\n\n  @@index([messageId])\n}\n\nmodel VisitaChatRead {\n  visitaId   String\n  userId     String\n  lastReadAt DateTime @default(now()) @updatedAt\n\n  visita Visita @relation(fields: [visitaId], references: [id], onDelete: Cascade)\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@id([visitaId, userId])\n  @@index([userId, lastReadAt])\n}\n\nmodel GrupoMiembro {\n  id         String @id @default(cuid())\n  personalId String\n  grupoId    String\n\n  personal Personal @relation(fields: [personalId], references: [id], onDelete: Cascade)\n  grupo    Grupo    @relation(fields: [grupoId], references: [id], onDelete: Cascade)\n\n  @@unique([personalId, grupoId])\n}\n\nmodel Sector {\n  id        String    @id @default(cuid())\n  nombre    String    @unique\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  deletedAt DateTime?\n\n  clientes Cliente[]\n  admins   SectorAdmin[]\n}\n\nmodel SectorAdmin {\n  id       String @id @default(cuid())\n  sectorId String\n  userId   String\n\n  sector Sector @relation(fields: [sectorId], references: [id], onDelete: Cascade)\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([sectorId, userId])\n}\n\n// ──────────────────────────────────────────────\n// Notificaciones WhatsApp\n// ──────────────────────────────────────────────\n\nmodel NotificacionConfig {\n  id                     String   @id @default(cuid())\n  whatsappActivo         Boolean  @default(false)\n  whatsappPhoneNumberId  String?\n  whatsappBusinessId     String?\n  horaEnvioRecordatorio  String   @default(\"08:00\")\n  horaEnvioDigesto       String   @default(\"07:00\")\n  diasAnticipacion       Int      @default(1)\n  zonaHoraria            String   @default(\"America/Guayaquil\")\n  autoRespuestaActiva    Boolean  @default(false)\n  autoRespuestaContenido String?  @db.Text\n  forwardActivo          Boolean  @default(false)\n  forwardTelefono        String?\n  createdAt              DateTime @default(now())\n  updatedAt              DateTime @updatedAt\n}\n\nmodel NotificacionPlantilla {\n  id                            String           @id @default(cuid())\n  tipo                          TipoNotificacion @unique\n  nombre                        String\n  activa                        Boolean          @default(true)\n  // Template default (original, fijo en Meta)\n  contenidoOriginal             String?          @db.Text\n  whatsappDefaultTemplateName   String?\n  whatsappDefaultTemplateStatus String?\n  // Template personalizado (custom, editable)\n  whatsappTemplateName          String?\n  whatsappTemplateStatus        String?\n  whatsappTemplateVersion       Int              @default(1)\n  whatsappTemplateLanguage      String           @default(\"es\")\n  whatsappPendingTemplateName   String?\n  whatsappPendingTemplateStatus String?\n  contenido                     String           @db.Text\n  contenidoEnRevision           String?          @db.Text\n  variables                     String[]\n  createdAt                     DateTime         @default(now())\n  updatedAt                     DateTime         @updatedAt\n}\n\nmodel NotificacionLog {\n  id                 String             @id @default(cuid())\n  tipo               TipoNotificacion\n  destinatarioTipo   DestinatarioTipo\n  destinatarioId     String?\n  destinatarioNombre String?\n  telefono           String\n  mensaje            String             @db.Text\n  estado             EstadoNotificacion @default(PENDIENTE)\n  whatsappMessageId  String?\n  errorDetalle       String?            @db.Text\n  visitaId           String?\n  enviadoAt          DateTime?\n  createdAt          DateTime           @default(now())\n\n  visita Visita? @relation(fields: [visitaId], references: [id], onDelete: SetNull)\n}\n\n// ──────────────────────────────────────────────\n// Mobile auth / push\n// ──────────────────────────────────────────────\n\nmodel PushToken {\n  id         String   @id @default(cuid())\n  userId     String\n  token      String   @unique\n  platform   String\n  deviceName String?\n  lastUsedAt DateTime @default(now())\n  createdAt  DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n}\n\nmodel OtpCode {\n  id        String    @id @default(cuid())\n  phone     String\n  codeHash  String\n  expiresAt DateTime\n  attempts  Int       @default(0)\n  usedAt    DateTime?\n  createdAt DateTime  @default(now())\n\n  @@index([phone, createdAt])\n}\n\nmodel RefreshToken {\n  id         String    @id @default(cuid())\n  userId     String\n  tokenHash  String    @unique\n  expiresAt  DateTime\n  revokedAt  DateTime?\n  deviceInfo String?\n  createdAt  DateTime  @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n}\n\n// Historial de importaciones masivas de clientes (CSV). `results` guarda el\n// detalle por fila (ImportRowResult[]): fila, estado, nombre, clienteId, mensaje.\nmodel ClienteImport {\n  id          String   @id @default(cuid())\n  createdById String?\n  createdBy   User?    @relation(\"ClienteImportCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  // \"procesando\" | \"completado\" | \"cancelado\"\n  status      String   @default(\"procesando\")\n  total       Int\n  created     Int      @default(0)\n  skipped     Int      @default(0)\n  failed      Int      @default(0)\n  results     Json     @default(\"[]\")\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@index([createdAt])\n}\n\n/// Token de un solo uso para establecer una contraseña: la invitación de un\n/// usuario del portal, la de un cliente, o el restablecimiento de cualquiera de\n/// los dos. Solo se guarda el hash (sha256): el token en claro existe una vez,\n/// dentro del enlace, y ni siquiera nosotros podemos volver a leerlo.\n///\n/// Apunta a **un** cliente o a **un** usuario, nunca a los dos ni a ninguno\n/// (un CHECK lo obliga). Son dos tablas de identidad distintas —el personal\n/// vive en User, los clientes en Cliente— pero el enlace, la página y el\n/// vencimiento son los mismos, y partirlo en dos tablas habría significado\n/// duplicar todo eso para variar solo la clave foránea.\nmodel SetPasswordToken {\n  id        String    @id @default(cuid())\n  clienteId String?\n  userId    String?\n  tokenHash String    @unique\n  expiresAt DateTime\n  /// Cuándo alguien lo abrió y eligió una contraseña. Solo eso.\n  usedAt    DateTime?\n  /// Cuándo lo dimos de baja nosotros: porque se emitió uno más nuevo, o\n  /// porque se le revocó el acceso a la persona.\n  ///\n  /// Aparte de `usedAt` porque no son lo mismo y la diferencia se ve: decirle\n  /// \"este enlace ya se usó\" a quien nunca lo abrió lo manda a preguntarse\n  /// quién entró con él.\n  anuladoEl DateTime?\n  createdAt DateTime  @default(now())\n\n  cliente Cliente? @relation(fields: [clienteId], references: [id], onDelete: Cascade)\n  user    User?    @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([clienteId])\n  @@index([userId])\n}\n\n// ──────────────────────────────────────────────\n// Informes mensuales (PDFs)\n// ──────────────────────────────────────────────\n\nmodel Informe {\n  id                String    @id @default(cuid())\n  clienteId         String\n  /// Correlativo corto, para nombrarlo en voz alta. Como el de visitas y\n  /// órdenes: cada tabla tiene su propia secuencia y eso está bien, porque\n  /// nunca se muestra un número sin decir de qué es.\n  numero            Int       @unique @default(autoincrement())\n  titulo            String\n  /// La fecha que **sale impresa** en el PDF, y solo eso.\n  ///\n  /// Va aparte de `generatedAt` porque son dos hechos distintos: cuándo se\n  /// armó el archivo y con qué fecha se entrega. Un informe de agosto se puede\n  /// generar el 2 de septiembre y tiene que decir agosto; y regenerarlo para\n  /// corregir una foto no puede cambiarle la fecha al documento que el cliente\n  /// ya tiene. `generatedAt` sigue siendo el instante real, para auditoría.\n  fecha             DateTime  @db.Date\n  fechaDesde        DateTime?\n  fechaHasta        DateTime?\n  pdfKey            String\n  pdfUrl            String\n  // Per-informe signers: [{ nombre: string, cedula?: string }]. 1 to 3.\n  firmantes         Json      @default(\"[]\")\n  generatedById     String\n  /// Nombre de quien lo creó, congelado. El id sirve para filtrar; el texto es\n  /// lo que pasó, y sobrevive a que la cuenta se renombre o se borre.\n  generatedByNombre String?\n  generatedAt       DateTime  @default(now())\n\n  /// Quién y cuándo lo tocó por última vez. Nulo mientras nadie lo editó: eso\n  /// dice \"sigue como se creó\", que es distinto de \"lo actualizó quien lo hizo\".\n  updatedById     String?\n  updatedByNombre String?\n  updatedAt       DateTime @updatedAt\n\n  /// En qué versión va. Arranca en 1 y sube con cada edición.\n  versionActual Int @default(1)\n\n  cliente     Cliente           @relation(fields: [clienteId], references: [id], onDelete: Cascade)\n  generatedBy User              @relation(\"InformeGeneratedBy\", fields: [generatedById], references: [id], onDelete: Restrict)\n  updatedBy   User?             @relation(\"InformeUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull)\n  visitas     InformeVisita[]\n  secciones   InformeSeccion[]\n  versiones   InformeVersion[]\n  borradores  InformeBorrador[]\n\n  @@index([clienteId])\n  @@index([generatedAt])\n}\n\n/// Una versión del informe: **el PDF que se entregó en ese momento**.\n///\n/// El informe se puede editar, y editarlo no pisa lo anterior: cada generación\n/// deja su archivo. Esa era la razón por la que antes no se editaba —el cliente\n/// se quedaba con un PDF que ya no era el nuestro— y guardar las versiones es lo\n/// que la resuelve: el que él tiene sigue existiendo y se puede abrir.\n///\n/// El PDF es el documento. Las tablas `InformeSeccion` / `InformeSeccionFoto`\n/// son la versión **actual** —lo que se abre para editar—; una versión vieja\n/// conserva su archivo y, en `contenido`, con qué se armó.\nmodel InformeVersion {\n  id        String @id @default(cuid())\n  informeId String\n  /// 1, 2, 3… Único dentro del informe.\n  version   Int\n\n  titulo String\n  /// La que salió impresa en **esta** versión.\n  fecha  DateTime @db.Date\n  pdfKey String\n  pdfUrl String\n\n  /// Con qué se armó: secciones, fotos y firmantes tal como se mandaron. Es lo\n  /// que permite mirar una versión vieja sin depender de las tablas vivas, que\n  /// para entonces ya describen otra cosa.\n  contenido Json\n\n  generatedById     String?\n  generatedByNombre String?\n  generatedAt       DateTime @default(now())\n  /// Qué se cambió, si alguien lo escribió. Opcional a propósito: obligar a\n  /// justificar cada corrección hace que se escriba \"corrección\" y nada más.\n  nota              String?\n\n  informe     Informe @relation(fields: [informeId], references: [id], onDelete: Cascade)\n  generatedBy User?   @relation(\"InformeVersionGeneratedBy\", fields: [generatedById], references: [id], onDelete: SetNull)\n\n  @@unique([informeId, version])\n  @@index([informeId])\n}\n\n/// Un informe a medio armar.\n///\n/// No es un `Informe` sin PDF: un informe es un documento emitido, con número y\n/// archivo, y un borrador no tiene nada de eso — es el estado del asistente\n/// guardado para seguir después. Meterlos en la misma tabla obligaría a que\n/// todo lo que lista informes explique cuáles no lo son.\n///\n/// El contenido va como JSON y no en tablas: nada lo consulta por partes, y\n/// mientras se arma cambia de forma todo el tiempo.\nmodel InformeBorrador {\n  id        String  @id @default(cuid())\n  /// El mismo correlativo que los informes, **de la misma secuencia**.\n  ///\n  /// Un borrador se nombra en voz alta igual que un informe, así que necesita\n  /// número; y tiene que salir del mismo pozo, o el #17 sería dos cosas\n  /// distintas. Se pide al crearlo y el informe lo hereda al generarse: el\n  /// borrador #17 se convierte en el informe #17.\n  ///\n  /// Descartar un borrador deja un hueco en la numeración, igual que pasa con\n  /// las facturas. Es el precio de poder nombrarlo antes de que exista.\n  numero    Int     @unique\n  clienteId String?\n  titulo    String?\n  contenido Json\n\n  /// De qué informe es esta edición a medio hacer. Nulo = es un informe nuevo.\n  ///\n  /// Editar también se puede dejar por la mitad, y ese borrador no es \"un\n  /// informe nuevo\": al retomarlo hay que volver a la edición del mismo, o se\n  /// terminaría creando un duplicado del que se quería corregir.\n  informeId String?\n\n  createdById     String?\n  createdByNombre String?\n  createdAt       DateTime @default(now())\n  updatedById     String?\n  updatedByNombre String?\n  updatedAt       DateTime @updatedAt\n\n  cliente   Cliente? @relation(fields: [clienteId], references: [id], onDelete: Cascade)\n  /// Se va con el informe: un borrador de una edición de algo que ya no existe\n  /// no se puede retomar ni tiene a dónde volver.\n  informe   Informe? @relation(fields: [informeId], references: [id], onDelete: Cascade)\n  createdBy User?    @relation(\"InformeBorradorCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  updatedBy User?    @relation(\"InformeBorradorUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull)\n\n  @@index([updatedAt])\n  @@index([clienteId])\n  @@index([informeId])\n}\n\nmodel InformeVisita {\n  informeId String\n  visitaId  String\n\n  informe Informe @relation(fields: [informeId], references: [id], onDelete: Cascade)\n  visita  Visita  @relation(fields: [visitaId], references: [id], onDelete: Cascade)\n\n  @@id([informeId, visitaId])\n  @@index([visitaId])\n}\n\nmodel InformeSeccion {\n  id          String  @id @default(cuid())\n  informeId   String\n  /// Producto que origina la sección. Null = sección personalizada.\n  productoId  String?\n  titulo      String\n  descripcion String? @db.Text\n  orden       Int\n\n  /// Empieza en una hoja nueva. Para separar bloques que no se leen juntos.\n  saltoDePagina Boolean @default(false)\n  /// Cuántas fotos por fila: 2 (grandes), 3 (por defecto) o 4 (chicas). Es la\n  /// palanca de densidad — pocas fotos grandes llenan la hoja, muchas chicas la\n  /// dejan corta.\n  fotosPorFila  Int     @default(3)\n\n  informe  Informe              @relation(fields: [informeId], references: [id], onDelete: Cascade)\n  producto Producto?            @relation(fields: [productoId], references: [id], onDelete: SetNull)\n  fotos    InformeSeccionFoto[]\n\n  @@index([informeId])\n  @@index([productoId])\n}\n\n/// Una foto de una sección: puede venir de una visita (visitaMediaId) o haber\n/// sido subida directamente al informe. `key`/`url` siempre se guardan para que\n/// el informe siga siendo editable aunque se borre la media de la visita.\n/// Una foto de una sección del informe.\n///\n/// `key` y `url` son **lo que se imprimió**: el PDF ya salió con esa imagen y\n/// eso no cambia. Los otros dos campos dicen de dónde vino, y son excluyentes:\n///\n/// - `visitaMediaId` — de la galería de una visita. El archivo es de la visita.\n/// - `mediaId` — de la biblioteca. El archivo es de la biblioteca, y puede\n///   estar en un producto o en otro informe.\n///\n/// Los dos en null es una foto vieja, subida cuando el informe era el único\n/// dueño de su archivo. De quién es el archivo decide **quién lo borra**.\nmodel InformeSeccionFoto {\n  id            String  @id @default(cuid())\n  seccionId     String\n  orden         Int\n  key           String\n  url           String\n  visitaMediaId String?\n  mediaId       String?\n\n  seccion     InformeSeccion @relation(fields: [seccionId], references: [id], onDelete: Cascade)\n  visitaMedia VisitaMedia?   @relation(fields: [visitaMediaId], references: [id], onDelete: SetNull)\n  media       Media?         @relation(fields: [mediaId], references: [id], onDelete: SetNull)\n\n  @@index([seccionId, orden])\n  @@index([visitaMediaId])\n  @@index([mediaId])\n}\n\nmodel EmpresaConfig {\n  id        String   @id @default(\"default\")\n  nombre    String?\n  logoKey   String?\n  logoUrl   String?\n  updatedAt DateTime @updatedAt\n}\n\n/// A nombre de quién se emite un comprobante electrónico ante el SRI.\n///\n/// Es una **tabla y no una fila de configuración** porque el vivero factura con\n/// más de un RUC y elige cuál al emitir. Cada uno es un contribuyente distinto\n/// para el SRI: su propio certificado, su propia numeración y su propio trámite\n/// de ambiente de pruebas.\n///\n/// Los campos son los que el XML exige en `infoTributaria`, ni más ni menos.\nmodel Emisor {\n  id                       String  @id @default(cuid())\n  /// 13 dígitos. Es la identidad del emisor ante el SRI.\n  ruc                      String  @unique\n  razonSocial              String\n  nombreComercial          String?\n  /// Dirección de la matriz y del establecimiento que emite. El SRI las pide\n  /// por separado aunque casi siempre coincidan.\n  dirMatriz                String\n  direccionEstablecimiento String\n  /// Tres dígitos cada uno: \"001\". Con el secuencial forman \"001-002-000000001\".\n  establecimiento          String  @default(\"001\")\n  puntoEmision             String  @default(\"001\")\n\n  obligadoContabilidad  Boolean @default(true)\n  /// Número de resolución, cuando el SRI lo designó contribuyente especial.\n  contribuyenteEspecial String?\n  /// Número de resolución de agente de retención, si lo es.\n  agenteRetencion       String?\n\n  /// `PRUEBAS` (1) o `PRODUCCION` (2). Son dos mundos separados del SRI, con\n  /// distinta URL y distinta autorización: lo emitido en pruebas no vale nada.\n  ambiente AmbienteSri @default(PRUEBAS)\n\n  /// El `.p12` con el que se firma, **cifrado** (AES-256-GCM). Es una clave\n  /// privada que firma documentos tributarios en nombre de la empresa: no sale\n  /// nunca por una API, no se registra en logs y solo la lee el servidor al\n  /// momento de firmar.\n  certificado         Bytes?\n  /// Su contraseña, cifrada con la misma clave.\n  certificadoPassword Bytes?\n  /// A nombre de quién está el certificado y hasta cuándo sirve. Se leen del\n  /// propio `.p12` al cargarlo, para poder avisar antes de que caduque: vencido,\n  /// ese RUC deja de poder facturar.\n  certificadoSujeto   String?\n  certificadoVence    DateTime?\n\n  activo         Boolean @default(true)\n  /// El que viene elegido al emitir. Solo uno.\n  predeterminado Boolean @default(false)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  secuenciales SecuencialSri[]\n  facturas     Factura[]\n\n  @@index([activo])\n}\n\nenum AmbienteSri {\n  PRUEBAS\n  PRODUCCION\n}\n\n/// La numeración de cada serie del SRI.\n///\n/// Va por emisor, establecimiento, punto de emisión **y tipo de comprobante**:\n/// una factura y una nota de crédito llevan series distintas. Se incrementa con\n/// un `UPDATE ... RETURNING` atómico, que es lo único que evita que dos\n/// emisiones simultáneas pidan el mismo número — y un número repetido lo\n/// rechaza el SRI.\nmodel SecuencialSri {\n  id              String @id @default(cuid())\n  emisorId        String\n  establecimiento String\n  puntoEmision    String\n  /// `FACTURA`, `NOTA_CREDITO`… tal como los nombra la librería.\n  tipoDocumento   String\n  /// El último entregado. El próximo es este + 1.\n  valor           Int    @default(0)\n\n  emisor Emisor @relation(fields: [emisorId], references: [id], onDelete: Cascade)\n\n  @@unique([emisorId, establecimiento, puntoEmision, tipoDocumento])\n}\n\nmodel Firmante {\n  id        String   @id @default(cuid())\n  nombre    String\n  cedula    String?\n  isDefault Boolean  @default(false)\n  orden     Int      @default(0)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([isDefault])\n}\n\n// ──────────────────────────────────────────────\n// Libro de ventas\n//\n// Una orden es \"lo que se vendió\": existe desde que se hizo el trabajo, antes\n// de que exista factura. Toda la plata vive en `OrdenLinea`, venga de una\n// suscripción, de una visita única o (más adelante) de un bien. Así un reporte\n// de ventas es una sola consulta en vez de un union por cada tipo de ingreso,\n// y el historial completo de ventas queda en nuestra base.\n// ──────────────────────────────────────────────\n\n/// Tres estados y una sola idea: si la orden está viva y si se puede tocar.\n///\n/// No hay FACTURADA porque facturar dejó de ser un paso aparte —confirmar\n/// emite— así que CONFIRMADA **es** \"tiene factura viva\". Que esté cobrada o no\n/// se lee del saldo de esa factura, no del estado de la orden: son dos ejes\n/// distintos y mezclarlos obligaba a inventar un estado por combinación.\n///\n/// Una emisión fallida deja la orden en BORRADOR, que es el único estado\n/// editable: justo donde hay que estar para arreglar la causa.\nenum EstadoOrden {\n  BORRADOR\n  CONFIRMADA\n  ANULADA\n}\n\nmodel Orden {\n  id                String  @id @default(cuid())\n  clienteId         String\n  /// Con qué datos se va a facturar. Se elige al armar la orden, cuando el\n  /// vendedor tiene al cliente delante; al emitir ya es tarde para preguntar.\n  /// Nullable porque una orden puede existir antes de saberlo.\n  datoFacturacionId String?\n  /// Correlativo interno legible. No es el número de factura del SRI.\n  numero            Int     @unique @default(autoincrement())\n\n  /// De qué plan es esta orden, cuando es de un plan.\n  ///\n  /// Las visitas viven en `OrdenVisita` porque pueden ser **varias**; un plan\n  /// no: sus períodos se renuevan solos y cada orden cubre uno.\n  ///\n  /// Null y sin `OrdenVisita` = orden suelta, armada a mano.\n  suscripcionId String?\n  fecha         DateTime    @db.Date\n  estado        EstadoOrden @default(BORRADOR)\n  notas         String?     @db.Text\n\n  /// Totales denormalizados, recalculados desde las líneas en cada escritura.\n  subtotal Decimal @default(0) @db.Decimal(10, 2)\n  iva      Decimal @default(0) @db.Decimal(10, 2)\n  total    Decimal @default(0) @db.Decimal(10, 2)\n\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n  createdById String?\n  updatedById String?\n\n  cliente         Cliente          @relation(fields: [clienteId], references: [id], onDelete: Restrict)\n  datoFacturacion DatoFacturacion? @relation(fields: [datoFacturacionId], references: [id], onDelete: SetNull)\n  suscripcion     Suscripcion?     @relation(fields: [suscripcionId], references: [id], onDelete: Restrict)\n  createdBy       User?            @relation(\"OrdenCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  updatedBy       User?            @relation(\"OrdenUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull)\n  lineas          OrdenLinea[]\n  facturas        Factura[]\n  visitas         OrdenVisita[]\n\n  @@index([clienteId, fecha])\n  @@index([estado])\n  @@index([datoFacturacionId])\n  @@index([suscripcionId])\n}\n\n/// De qué visitas es una orden.\n///\n/// Es una lista y no una columna porque **una orden puede cubrir varias\n/// visitas**: es normal cobrar el mes entero de alguien de una vez. Lo mantiene\n/// el servidor desde la procedencia de las líneas, así que no se recibe de\n/// afuera — una asignación que no trajera trabajo sería una que no queda\n/// registrada en ningún lado.\n///\n/// Existe además de `OrdenLineaOrigen` porque contesta otra pregunta: aquélla\n/// dice de dónde sale cada peso, ésta \"¿de qué es esta orden?\", que es la que\n/// se hace primero y la que obligaba a recorrer las líneas.\nmodel OrdenVisita {\n  ordenId  String\n  visitaId String\n\n  orden  Orden  @relation(fields: [ordenId], references: [id], onDelete: Cascade)\n  /// `Restrict`: una visita con orden no se borra sin resolver la orden antes.\n  visita Visita @relation(fields: [visitaId], references: [id], onDelete: Restrict)\n\n  @@id([ordenId, visitaId])\n  @@index([visitaId])\n}\n\nmodel OrdenLinea {\n  id       String @id @default(cuid())\n  ordenId  String\n  posicion Int    @default(0)\n\n  /// Snapshot: sobrevive a que después renombren o borren el producto.\n  descripcion    String\n  cantidad       Decimal @default(1) @db.Decimal(10, 2)\n  precioUnitario Decimal @db.Decimal(10, 2)\n  ivaTasa        Decimal @default(0) @db.Decimal(5, 2)\n  subtotal       Decimal @db.Decimal(10, 2)\n  iva            Decimal @db.Decimal(10, 2)\n  total          Decimal @db.Decimal(10, 2)\n\n  /// Qué se vendió. Obligatorio: de acá sale el `codigoPrincipal` que el SRI\n  /// pide en cada detalle, así que una línea sin producto sería una venta que\n  /// no se puede cobrar. Es además lo que hace que un reporte por producto sea\n  /// un `groupBy` y no una reconstrucción.\n  productoId        String\n  /// **Qué variante se vendió. Siempre hay una.**\n  ///\n  /// Todo producto tiene exactamente una variante —un servicio y un bien sin\n  /// opciones incluidos— así que acá nunca falta. Antes era opcional \"porque un\n  /// servicio no tiene\", y eso hacía que una línea apuntara a un producto o a\n  /// una variante según el tipo: dos formas para la misma cosa, y una rama en\n  /// cada lugar que preguntaba el SKU, el precio o el stock.\n  ///\n  /// De acá salen el SKU impreso y el stock que baja.\n  varianteId        String\n  suscripcionItemId String?\n  periodoInicio     DateTime? @db.Date\n  periodoFin        DateTime? @db.Date\n\n  orden           Orden              @relation(fields: [ordenId], references: [id], onDelete: Cascade)\n  /// `Restrict` y no `SetNull`: un producto que ya se vendió no se puede\n  /// borrar. Perder el vínculo dejaría la línea fuera de todo reporte y la\n  /// factura sin con qué reconciliarse.\n  producto        Producto           @relation(fields: [productoId], references: [id], onDelete: Restrict)\n  /// `Restrict` por lo mismo que el producto: una variante ya vendida no se\n  /// borra. Eso hace, de paso, que sacar un eje avise en vez de romper.\n  variante        Variante           @relation(fields: [varianteId], references: [id], onDelete: Restrict)\n  suscripcionItem SuscripcionItem?   @relation(fields: [suscripcionItemId], references: [id], onDelete: SetNull)\n  /// De qué trabajos de visita sale esta línea. Pueden ser varios.\n  origenes        OrdenLineaOrigen[]\n\n  /// Impide facturar dos veces el mismo período de la misma suscripción.\n  @@unique([suscripcionItemId, periodoInicio])\n  @@index([ordenId, posicion])\n  @@index([productoId])\n  @@index([varianteId])\n}\n\n/// Qué trabajo de qué visita paga una línea de orden.\n///\n/// Era una columna única en `OrdenLinea`, y eso obligaba a una línea por\n/// visita: el mismo producto hecho en dos visitas salía dos veces en la misma\n/// orden, lo que no le dice nada a nadie —es el mismo producto— y encima\n/// duplicaba la decisión de precio. Ahora una línea junta los dos trabajos.\n///\n/// `visitaProductoId` sigue siendo **único en toda la tabla**: eso es lo que\n/// impide cobrar el mismo trabajo dos veces, y no depende de ninguna\n/// validación de aplicación.\nmodel OrdenLineaOrigen {\n  ordenLineaId     String\n  visitaProductoId String @unique\n\n  ordenLinea     OrdenLinea     @relation(fields: [ordenLineaId], references: [id], onDelete: Cascade)\n  /// `Restrict`: el trabajo facturado no se borra. Como `VisitaProducto`\n  /// cascadea desde `Visita`, esto también protege a la visita entera.\n  visitaProducto VisitaProducto @relation(fields: [visitaProductoId], references: [id], onDelete: Restrict)\n\n  @@id([ordenLineaId, visitaProductoId])\n  @@index([ordenLineaId])\n}\n\nenum EstadoFactura {\n  PENDIENTE\n  FIRMADO\n  ENVIADO_SRI\n  AUTORIZADO\n  RECHAZADO\n}\n\n/// Qué comprobante se emitió por una orden.\nenum TipoDocumento {\n  FACTURA\n  /// La forma de corregir una factura que el SRI ya autorizó. Vive en la misma\n  /// tabla porque es otro comprobante: se firma, se manda y se consulta igual.\n  NOTA_CREDITO\n}\n\n/// Los datos con los que se le emite una factura a un cliente.\n///\n/// Van aparte del Cliente porque uno puede facturar de más de una forma: a\n/// nombre propio y al de su empresa, o a distintas razones sociales de un mismo\n/// contacto. Y porque el nombre con el que se lo conoce en el portal no tiene\n/// por qué ser la razón social del SRI.\n///\n/// Editarlo no rompe el historial: cada Factura guarda además un snapshot de la\n/// razón social e identificación con las que se emitió.\nmodel DatoFacturacion {\n  id        String @id @default(cuid())\n  clienteId String\n\n  /// `CEDULA` o `RUC`. La cédula se valida por módulo 10 antes de emitir.\n  tipoIdentificacion TipoIdentificacion\n  identificacion     String\n  /// Lo que se imprime en la factura, no el nombre del portal.\n  razonSocial        String\n  /// Natural o jurídica.\n  tipoPersona        TipoPersona\n  direccion          String?\n  telefono           String?\n  email              String?\n\n  /// El que se propone al facturar.\n  esPredeterminado Boolean @default(false)\n  /// Los archivados no se ofrecen, pero las facturas viejas los siguen citando.\n  archivado        Boolean @default(false)\n\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n  createdById String?\n  updatedById String?\n\n  cliente   Cliente   @relation(fields: [clienteId], references: [id], onDelete: Cascade)\n  createdBy User?     @relation(\"DatoFacturacionCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  updatedBy User?     @relation(\"DatoFacturacionUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull)\n  facturas  Factura[]\n  ordenes   Orden[]\n\n  /// No se repite la misma identificación dos veces en el mismo cliente.\n  @@unique([clienteId, identificacion])\n  @@index([clienteId, archivado])\n}\n\nenum TipoIdentificacion {\n  CEDULA\n  RUC\n}\n\nmodel Factura {\n  id      String @id @default(cuid())\n  ordenId String\n\n  /// Con qué RUC se emitió.\n  emisorId String?\n  emisor   Emisor? @relation(fields: [emisorId], references: [id], onDelete: Restrict)\n\n  /// ─── Lo que devuelve el SRI ──────────────────────────────────────────\n  ///\n  /// En el esquema *offline* la clave de acceso **es** el número de\n  /// autorización: se calcula acá antes de mandar nada, y el SRI la confirma.\n  claveAcceso       String?      @unique\n  /// Contra qué mundo se emitió. Lo de `PRUEBAS` no vale como comprobante.\n  ambienteSri       AmbienteSri?\n  /// `AUTORIZADO`, `ENVIADO`, `DEVUELTO`… tal como lo reporta la emisión.\n  estadoSri         String?\n  fechaAutorizacion DateTime?\n  /// Dónde quedó el XML firmado y autorizado, en R2. Hay que conservarlo.\n  xmlKey            String?\n  /// Lo que el SRI respondió cuando rechazó, para poder mostrarlo entero.\n  mensajesSri       Json?\n\n  /// Cuándo se le mandó al cliente y a qué correo. Sin esto no hay forma de\n  /// saber si le llegó, y el reflejo es mandarla de nuevo \"por si acaso\".\n  enviadoEl DateTime?\n  enviadoA  String?\n\n  /// Qué factura corrige esta nota de crédito, y por qué. El SRI exige las dos\n  /// cosas en el XML: sin el documento modificado la nota no se refiere a nada.\n  facturaModificadaId String?\n  facturaModificada   Factura?  @relation(\"NotasDeCredito\", fields: [facturaModificadaId], references: [id], onDelete: Restrict)\n  notasDeCredito      Factura[] @relation(\"NotasDeCredito\")\n  motivo              String?\n\n  /// `001-001-000000123`. Único **por tipo**: una factura y una nota de\n  /// crédito tienen cada una su propia serie, así que `001-001-000000001`\n  /// existe una vez de cada.\n  numero       String\n  tipo         TipoDocumento @default(FACTURA)\n  fechaEmision DateTime      @db.Date\n  estado       EstadoFactura @default(PENDIENTE)\n  /// El número de autorización que devolvió el SRI. En el esquema offline es\n  /// la misma clave de acceso, pero se guarda tal como vino.\n  autorizacion String?\n\n  /// Con qué datos se emitió. El id es la referencia; los dos campos de abajo\n  /// son el snapshot y son la verdad — el dato puede editarse o archivarse, y\n  /// el papel que recibió el cliente no cambia.\n  datoFacturacionId String?\n  razonSocial       String?\n  identificacion    String?\n\n  subtotal0       Decimal  @default(0) @db.Decimal(10, 2)\n  subtotalGravado Decimal  @default(0) @db.Decimal(10, 2)\n  iva             Decimal  @default(0) @db.Decimal(10, 2)\n  total           Decimal  @default(0) @db.Decimal(10, 2)\n  /// Lo que falta cobrar: el total menos los cobros registrados. Se recalcula\n  /// desde `Cobro` en cada movimiento, nunca restándole al valor guardado.\n  saldo           Decimal? @db.Decimal(10, 2)\n\n  anulada   Boolean  @default(false)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  orden           Orden                  @relation(fields: [ordenId], references: [id], onDelete: Restrict)\n  datoFacturacion DatoFacturacion?       @relation(fields: [datoFacturacionId], references: [id], onDelete: SetNull)\n  lineas          FacturaLinea[]\n  movimientos     MovimientoInventario[]\n\n  cobros Cobro[]\n\n  @@unique([tipo, numero])\n  @@index([ordenId])\n  @@index([estado])\n  @@index([facturaModificadaId])\n}\n\n/// Un cobro contra una factura.\n///\n/// No viaja a ningún lado. Al SRI la forma de pago se le declara **al emitir**,\n/// y el comprobante ya salió: esto es la cuenta corriente del vivero, no un\n/// dato tributario. Por eso las formas de pago son las que usa la gente, no el\n/// catálogo del SRI.\nmodel Cobro {\n  id         String    @id @default(cuid())\n  facturaId  String\n  /// El día que entró la plata, que puede no ser el día que se registra.\n  fecha      DateTime  @db.Date\n  monto      Decimal   @db.Decimal(10, 2)\n  formaPago  FormaPago\n  /// N° de transferencia, de cheque, del voucher. Lo que permite encontrarlo.\n  referencia String?\n  nota       String?\n\n  createdAt       DateTime @default(now())\n  createdById     String?\n  /// El nombre congelado: el id se queda sin dueño si la cuenta se elimina.\n  createdByNombre String?\n\n  factura   Factura @relation(fields: [facturaId], references: [id], onDelete: Cascade)\n  createdBy User?   @relation(\"CobroCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n\n  @@index([facturaId])\n}\n\nenum FormaPago {\n  EFECTIVO\n  TRANSFERENCIA\n  TARJETA\n  CHEQUE\n  OTRO\n}\n\n/// Lo que salió impreso en el documento, línea por línea.\n///\n/// Existe porque la factura **puede no tener la forma de la orden**: lo normal\n/// acá es cobrar varios trabajos de un período como una sola línea de\n/// \"servicio de mantenimiento\". Mientras las dos formas eran la misma, la\n/// factura se podía reconstruir desde la orden; en cuanto pueden diferir, esa\n/// reconstrucción es una mentira sobre un documento que ya se entregó.\n///\n/// No hay puente hacia `OrdenLinea` a propósito: la procedencia de cada peso\n/// —qué visita, qué período— vive en la orden, que es el libro de ventas. Esto\n/// es el espejo de lo legal. Lo que ata las dos caras es que **cuadren**: misma\n/// base imponible por cada tasa.\nmodel FacturaLinea {\n  id        String @id @default(cuid())\n  facturaId String\n  posicion  Int    @default(0)\n\n  /// Snapshot de lo que salió impreso: va tal cual al `descripcion` del\n  /// detalle del XML.\n  descripcion    String\n  cantidad       Decimal @default(1) @db.Decimal(10, 2)\n  precioUnitario Decimal @db.Decimal(10, 2)\n  ivaTasa        Decimal @default(0) @db.Decimal(5, 2)\n  subtotal       Decimal @db.Decimal(10, 2)\n  iva            Decimal @db.Decimal(10, 2)\n  total          Decimal @db.Decimal(10, 2)\n\n  /// De dónde sale el `codigoPrincipal`, y con qué queda asociada la venta.\n  productoId String\n  /// Qué variante salió. Siempre hay una: su SKU es lo que se imprime como\n  /// `codigoPrincipal`, y es de dónde se descontó el stock.\n  varianteId String\n\n  factura  Factura  @relation(fields: [facturaId], references: [id], onDelete: Cascade)\n  variante Variante @relation(fields: [varianteId], references: [id], onDelete: Restrict)\n  /// `Restrict` como en `OrdenLinea`: un producto ya facturado no se borra, o\n  /// la factura se queda sin con qué reconciliarse.\n  producto Producto @relation(fields: [productoId], references: [id], onDelete: Restrict)\n\n  @@index([facturaId, posicion])\n  @@index([productoId])\n  @@index([varianteId])\n}\n",
